ROWS = [
dict(id='T187',
 x='Moved on 12 Nov 2026 to the list of open problems in mathematics generally (06_math_research/top200_general_2026_11_10, seed_from_probability.tsv): Quantum unique ergodicity: spectral geometry.',
 d='DYN',
 t='Quantum unique ergodicity on negatively curved manifolds (Rudnick–Sarnak)',
 s='Let (M, g) be a compact connected Riemannian manifold without boundary and with negative sectional curvature, and let (u_n) be any orthonormal basis of L²(M) consisting of Laplace eigenfunctions, −Δu_n = λ_n u_n with λ_n → ∞. Rudnick and Sarnak conjecture that the whole sequence equidistributes: the only semiclassical measure is the Liouville measure on the unit cosphere bundle S*M, and in particular the probability measures |u_n(x)|² dvol(x) converge weakly to the normalised Riemannian volume.',
 c="Quantum ergodicity (Shnirelman, Zelditch, Colin de Verdière) gives the same conclusion along a density-one subsequence for any manifold with ergodic geodesic flow; the conjecture says there are no exceptional subsequences when the flow is Anosov. Ergodicity of the flow alone is not enough: Hassell (Ann. of Math. 171 (2010)) showed that generic Bunimovich stadia are not quantum uniquely ergodic. Compare T054 (the analogue for eigenvectors of random regular graphs) and T106 (Berry's random-wave model for the same eigenfunctions).",
 src='Z. Rudnick and P. Sarnak, The behaviour of eigenstates of arithmetic hyperbolic manifolds, Comm. Math. Phys. 161 (1994) 195–213',
 loc="S. Nonnenmacher, Quantum ergodicity and semiclassical measures: mathematical results, arXiv:2606.12098, Section 4: 'In 1994, Rudnick and Sarnak stated a conjecture specific to the manifolds of negative curvature (on which the geodesic flow is Anosov). Conjecture 1 (Quantum Unique Ergodicity). Take (M, g) a compact manifold of negative curvature (without boundary). Then there exist no exceptional eigemodes of the Laplacian ... In other words, for these manifolds there exists a unique semiclassical measure, which is the Liouville measure'; Section 4.1: 'The conjecture remains open, even in the case of manifolds of constant negative curvature.'",
 url='https://arxiv.org/abs/2606.12098',
 why='QUE is the sharpest form of the correspondence between classical chaos and the high-energy behaviour of quantum states, and it is the template for delocalisation questions about eigenvectors throughout random matrix theory and spectral graph theory. The partial results have required new ideas from measure rigidity, entropy theory and harmonic analysis.',
 st="For joint eigenfunctions of the Laplacian and the Hecke operators on arithmetic surfaces, Lindenstrauss (Ann. of Math. 163 (2006) 165–219) proved arithmetic QUE, completed for the modular surface by Soundararajan's escape-of-mass bound (Ann. of Math. 172 (2010)); Brooks and Lindenstrauss (Invent. Math. 198 (2014)) need only one Hecke operator. Without arithmetic structure, Anantharaman (Ann. of Math. 168 (2008)) showed every semiclassical measure has positive entropy, Anantharaman and Nonnenmacher (math-ph/0610019) at least half the maximal entropy in constant curvature, Dyatlov and Jin (arXiv:1705.05019) that semiclassical measures on hyperbolic surfaces have full support, and Dyatlov, Jin and Nonnenmacher (arXiv:1906.08923) the same for surfaces of variable negative curvature. Uniqueness of the semiclassical measure is not known for any compact negatively curved manifold without arithmetic symmetry. Open.",
 n="Fame: among the best-known problems of mathematical physics and spectral geometry; Lindenstrauss's Fields Medal citation names arithmetic QUE."),
dict(id="T188", d="COMB", t="Irreducibility of random 0–1 polynomials (Odlyzko–Poonen)",
 s="Let P_d(x) = x^d + A_{d−1}x^{d−1} + ⋯ + A_1 x + 1, where A_1, …, A_{d−1} are independent and uniform on {0, 1}. Odlyzko and Poonen conjectured that P(P_d is irreducible in Z[x]) → 1 as d → ∞.",
 c="The same question is asked for other coefficient laws, for instance independent uniform coefficients in {−1, 1} or in a fixed finite set, and is usually strengthened to the statement that the Galois group is the full symmetric group with probability tending to one. A related problem is van der Waerden's conjecture on the Galois groups of polynomials with coefficients in a growing box (Anderson, Chow, Dietmann and Hokken, arXiv:2608.22297), where the degree is fixed and the height grows; here the height is fixed and the degree grows.",
 src="A. M. Odlyzko and B. Poonen, Zeros of polynomials with 0,1 coefficients, Enseign. Math. (2) 39 (1993) 317–348",
 loc="E. Breuillard and P. P. Varjú, Irreducibility of random polynomials of large degree, arXiv:1810.13360, Section 1: 'Let P(x) = x^d + A_{d−1}x^{d−1} + ... + A_1x + 1 ∈ Z[x] be a random polynomial with independent coefficients A_1, ..., A_{d−1} taking values in 0 and 1 with equal probability. Odlyzko and Poonen [31] conjectured that the probability that P is irreducible in Z[x] converges to 1 as d → ∞. The best known lower bound in this problem is due to Konyagin [26] who proved that P(P is irreducible) > c/log d'.",
 url="https://arxiv.org/abs/1810.13360",
 why="The problem asks whether algebraic structure in a random object of large size is as rare as it looks, and its solution seems to need probabilistic input (equidistribution of random walks modulo primes) and arithmetic input at the same time. It has become a test case for combining random walks on finite fields with sieve methods.",
 st="Konyagin (Acta Arith. 88 (1999) 333–350) proved a lower bound c/log d. Breuillard and Varjú (arXiv:1810.13360, Acta Math. 223 (2019) 195–249) proved the conjecture, with Galois group containing A_d, assuming the Riemann hypothesis for Dedekind zeta functions. Unconditionally, Bary-Soroker and Kozma (arXiv:1710.05165) proved irreducibility with probability tending to one for coefficients uniform on {1, …, L} for suitable L such as 210, and Bary-Soroker, Koukoulopoulos and Kozma (arXiv:2007.14567) for coefficients uniform on at least 35 consecutive integers, together with a positive lower bound for any arithmetic progression of at least two terms. Klurman and Matei (arXiv:2511.10359) treat random multiplicative signs. Kogler (arXiv:2609.26771) proves the conjecture unconditionally: a monic polynomial with constant coefficient 1 and the other coefficients independent and uniform on {0, 1} is irreducible over Q with probability tending to 1. The preprint is not yet refereed.",
 n="Fame borderline (my judgment): well known in probabilistic number theory and among probabilists working on random polynomials; the GRH-conditional solution and the unconditional large-alphabet results are recent and widely cited."),
dict(id="T189", x="SOLVED (claimed, unrefereed), 14 Nov 2026: the OpenAI math release preprint 'A Fully Polynomial Randomized Approximation Scheme for Perfect Matchings in General Graphs' (23 Sep 2026, github.com/openai/math, Thm 1.1) claims an FPRAS for every finite simple graph, with a Lean statement and proof module; C. Liu and B. Meng, A simplified proof of the FPRAS for counting perfect matchings (arXiv:2610.26803, 19 Oct 2026), give a shorter proof of the same claim. AI-written and unrefereed; this records the claim, not a check of the proof. Replacement row to be screened.", d="RW", t="An FPRAS for counting perfect matchings in general graphs",
 s="Is there a fully polynomial randomised approximation scheme for the number of perfect matchings of an arbitrary finite graph? Equivalently, given a graph G on n vertices and ε > 0, can one output with probability at least 3/4 a number within a factor 1 ± ε of the number of perfect matchings of G in time polynomial in n and 1/ε, without assuming G bipartite?",
 c="For bipartite graphs this is the permanent of a 0–1 matrix, solved by Jerrum, Sinclair and Vigoda; for planar graphs the count is exact in polynomial time by Kasteleyn's Pfaffian method. Exact counting is #P-complete (Valiant 1979). The problem is the main open case of the Markov chain Monte Carlo programme for matchings.",
 src="M. Jerrum, A. Sinclair and E. Vigoda, A polynomial-time approximation algorithm for the permanent of a matrix with nonnegative entries, J. ACM 51 (2004) 671–697",
 loc="D. Štefankovič, E. Vigoda and J. Wilmes, On counting perfect matchings in general graphs, arXiv:1712.07504, abstract: 'it has remained an open question whether there exists an FPRAS for counting perfect matchings in general graphs. In fact, it was unresolved whether the same Markov chain defined by JSV is rapidly mixing in general. In this paper, we show that it is not.'",
 url="https://arxiv.org/abs/1712.07504",
 why="Approximate counting of perfect matchings is the problem that created the canonical-path and Markov-chain technology of the 1980s, and the bipartite solution is one of the landmark results of the area. Whether non-bipartite graphs are equally tractable decides whether the Gallai–Edmonds structure of factor-critical subgraphs is a genuine obstruction to rapid mixing or only to current proofs.",
 st="Jerrum and Sinclair handled graphs whose ratio of near-perfect to perfect matchings is polynomially bounded, including dense graphs. Štefankovič, Vigoda and Wilmes (arXiv:1712.07504) proved torpid mixing of the Jerrum–Sinclair–Vigoda chain on general graphs for every weighting of hole patterns and gave an FPRAS for graphs close to bipartite, fixed-parameter in the largest order of a factor-critical subgraph. Alimohammadi, Anari, Shiragur and Vuong (arXiv:2102.02708) count matchings of given size in planar graphs via fractional log-concavity. For the permanent, Chen, Vigoda and Yang (arXiv:2608.26599) give a faster FPRAS. An FPRAS for counting perfect matchings in general graphs, credited to OpenAI (2026), samples weighted perfect matchings through a restricted Poincaré inequality for pairs of matchings; Liu and Meng (arXiv:2610.26803) give a simplified, self-contained proof with the same guarantee. Neither is refereed.",
 n="Fame: a standard open problem in the theory of approximate counting and Markov chain Monte Carlo, listed alongside #BIS (T195) in surveys of the area."),
dict(id="T190", d="BM", t="Anomalous dissipation for stationary solutions of the stochastically forced 3D Navier–Stokes equations",
 s="Consider the incompressible Navier–Stokes equations on T³ with viscosity ν and additive Gaussian forcing, white in time and smooth in space, with energy input ε fixed. Show that there exist statistically stationary martingale solutions u^ν with lim_{ν→0} ν E‖u^ν‖²_{L²} = 0 (weak anomalous dissipation, WAD); Bedrossian, Coti Zelati, Punshon-Smith and Weber conjecture that WAD holds whenever the forcing satisfies a suitable Hörmander bracket condition.",
 c="By the theorem of the same authors, WAD implies Kolmogorov's 4/5 law for the third-order longitudinal structure function, averaged over directions and over an inertial range; the row is therefore the open hypothesis under which the 4/5 law is a theorem. WAD fails for some degenerate forcings (a single forced mode gives an Ornstein–Uhlenbeck solution), so a non-degeneracy condition is needed. Distinct from T091 (uniqueness and regularity of the same equations).",
 src="J. Bedrossian, M. Coti Zelati, S. Punshon-Smith and F. Weber, A sufficient condition for the Kolmogorov 4/5 law for stationary martingale solutions to the 3D Navier–Stokes equations, Comm. Math. Phys. 367 (2019) 1045–1075, arXiv:1803.09695",
 loc="arXiv:1803.09695, Definition 1.1: 'We say that a sequence {u}ν>0 of stationary martingale solutions satisfies weak anomalous dissipation if lim_{ν→0} νE‖u‖²_{L²_x} = 0. (WAD)'; Remark 1.6: 'It is an open problem to prove existence of solutions satisfying (WAD) ... It is natural to conjecture that (WAD) holds whenever the stochastic forcing satisfies some suitable Hörmander bracket condition'; list of open problems: 'By far, the most important question is the existence of suitable stationary martingale solutions that satisfy (WAD) (at least).'",
 url="https://arxiv.org/abs/1803.09695",
 why="Anomalous dissipation is the founding assumption of Kolmogorov's theory of turbulence, and the 4/5 law is the only exact result that theory predicts. A proof of WAD for randomly forced Navier–Stokes would give the first derivation of the 4/5 law from the equations for a natural class of flows.",
 st="Onsager's conjecture on energy conservation for Euler is resolved (Isett; Buckmaster, De Lellis, Székelyhidi and Vicol), and Bruè, Colombo, Crippa and De Lellis (arXiv:2212.08413) construct deterministic forcings for which forced 3D Navier–Stokes solutions dissipate anomalously, with Onsager-critical bounds. For stochastic forcing, the 4/5 law is proved conditionally on WAD (arXiv:1803.09695); the analogous laws are proved for passive scalars advected by stochastic Navier–Stokes (Bedrossian, Blumenthal and Punshon-Smith) and for stochastic Burgers (Gao and Kuksin, arXiv:2209.14288, weak and strong 4/5 laws for the space-periodic 1d equation), and Hofmanová, Pappalettera, Zhu and Zhu (arXiv:2305.08090) obtain anomalous dissipation of a passive scalar. WAD itself has not been established for any non-degenerate stochastic forcing. Open.",
 n="Fame borderline (my judgment): the precise WAD formulation is recent, but it is the rigorous form of anomalous dissipation, which is the central unproved hypothesis of turbulence theory."),
dict(id='T191',
 x="Moved on 12 Nov 2026 to the list of open problems in mathematics generally (06_math_research/top200_general_2026_11_10, seed_from_probability.tsv): Babai's diameter conjecture: group theory.",
 d='RW',
 t="Polynomial diameter of every Cayley graph of the symmetric group (Babai's conjecture)",
 s="Show that there is an absolute constant C such that for every n and every generating set A of the symmetric group Sym(n) or the alternating group Alt(n), every element is a product of at most n^C elements of A ∪ A^{−1}; that is, the diameter of every connected Cayley graph of these groups is polynomial in n. This is the case of Babai's conjecture that diam Cay(G, A) ≤ (log |G|)^C for every non-abelian finite simple group G.",
 c='By standard comparison arguments a polynomial diameter bound gives a polynomial bound on the mixing time of the lazy random walk on every Cayley graph of Sym(n) up to a factor depending on |A|, which is how the problem enters random walks on groups. Compare T085 (random Cayley graphs of Sym(n) are expanders) and T124 (uniform expansion of SL_2(F_p)), which ask for spectral gaps rather than diameters.',
 src='L. Babai and Á. Seress, On the diameter of permutation groups, European J. Combin. 13 (1992) 231–243',
 loc="H. A. Helfgott and Á. Seress, On the diameter of permutation groups, arXiv:1109.3550, abstract: 'It has long been conjectured that the diameter of the symmetric group of degree n is polynomially bounded in n, but the best previously known upper bound was exponential in √(n log n). We give a quasipolynomial upper bound, namely, diam(G) = exp(O((log n)^4 log log n)) ... This addresses a key open case of Babai's conjecture on diameters of simple groups.'",
 url='https://arxiv.org/abs/1109.3550',
 why='The diameter of a Cayley graph governs how fast any generating set mixes the group, and the symmetric group is the case where character-theoretic tools give the least. For simple groups of Lie type of bounded rank the conjecture is a theorem (Helfgott; Breuillard, Green and Tao; Pyber and Szabó), so the symmetric and alternating groups are the main remaining family.',
 st='Babai and Seress (1988) proved exp((1 + o(1))√(n log n)); Helfgott and Seress (Ann. of Math. 179 (2014) 611–658, arXiv:1109.3550) proved the quasipolynomial bound exp(O((log n)^4 log log n)). For two random generators the diameter is polynomial with high probability (Babai and Hetyei; Schlage-Puchta; Helfgott, Seress and Zuk, J. Algebra 421 (2015), give O(n²(log n)^c)). Keevash and Lifshitz (arXiv:2307.15030) obtain essentially sharp diameter estimates for generating sets of density at least exponential in −n. Computations of Chervov, Fedoriaka, Konstantinova and Naumov (arXiv:2509.19162) suggest that the largest diameters for two generators are of order n²/2. No polynomial bound is known for general generating sets. Open.',
 n='Fame: a central conjecture in the combinatorics of finite groups, with a long line of work by Babai, Seress, Helfgott and others; known well beyond group theory through its links with expansion and mixing.'),
dict(id='T192',
 x='Moved on 12 Nov 2026 to the list of open problems in mathematics generally (06_math_research/top200_general_2026_11_10, seed_from_probability.tsv): Deterministic RIP matrices beyond the square-root barrier: explicit constructions.',
 d='STAT',
 t='Deterministic matrices with the restricted isometry property beyond the square-root bottleneck',
 s='Construct, deterministically and in time polynomial in N, a family of m × N matrices Φ with N/m → ∞ that satisfy the restricted isometry property of order k with a fixed constant δ < 1 (that is, (1 − δ)‖x‖² ≤ ‖Φx‖² ≤ (1 + δ)‖x‖² for all k-sparse x) with k ≥ m^{1−o(1)}, as random Gaussian or Bernoulli matrices do with high probability for k of order m/log(N/m). Even k ≥ m^{1/2+γ} for a fixed γ that is not tiny is open.',
 c='Coherence-based arguments, which bound inner products of pairs of columns, cannot give k beyond order √m: this is the square-root bottleneck. The problem is a derandomisation question for a high-dimensional probabilistic property, closely related to bounding clique numbers of Paley-type graphs; certifying RIP of a given matrix is NP-hard (Bandeira, Dobriban, Mixon and Sawin, IEEE Trans. Inform. Theory 59 (2013) 3448–3450).',
 src='J. Bourgain, S. Dilworth, K. Ford, S. Konyagin and D. Kutzarova, Explicit constructions of RIP matrices and related problems, Duke Math. J. 159 (2011) 145–185; T. Tao, Open question: deterministic UUP matrices, blog post, 2007',
 loc="S. Satake and Y. Gu, On compressed sensing matrices breaking the square-root bottleneck, arXiv:2010.11179, abstract: 'One of challenging problems in compressed sensing is to construct deterministic matrices having restricted isometry property (RIP). So far, there are only a few publications providing deterministic RIP matrices beating the square-root bottleneck on the sparsity level.' Bandeira, Fickus, Mixon and Wong, arXiv:1202.1234, abstract: 'While random matrices are known to satisfy this property with high probability, deterministic constructions have found less success.'",
 url='https://arxiv.org/abs/2010.11179',
 why='The restricted isometry property is the standard sufficient condition for exact sparse recovery, and random matrices achieve the optimal sparsity level. Whether the same can be done without randomness is a clean test of how much of high-dimensional probability can be derandomised, and progress has required additive combinatorics.',
 st='Bourgain, Dilworth, Ford, Konyagin and Kutzarova (Duke 2011) gave the only unconditional construction beating the bottleneck, with k = m^{1/2+ε_0} for a very small ε_0, later increased slightly by Mixon (Appl. Numer. Harmon. Anal., Birkhäuser (2015) 389–417). Bandeira, Fickus, Mixon and Wong (arXiv:1202.1234) conjectured that Paley equiangular tight frames are RIP; Bandeira, Mixon and Moreira obtained a construction conditional on a clique-number bound for Paley graphs (Int. Math. Res. Not. IMRN 2017, 372–381), and Satake and Gu (arXiv:2010.11179) one conditional on the generalized Paley graph conjecture. No unconditional deterministic construction reaches k = m^{1/2+γ} for moderate γ. Open.',
 n="Fame borderline (my judgment): well known in compressed sensing, applied harmonic analysis and high-dimensional probability since Tao's 2007 formulation; less known in pure probability."),
dict(id='T193',
 x='Moved on 12 Nov 2026 to the list of open problems in mathematics generally (06_math_research/top200_general_2026_11_10, seed_from_probability.tsv): Sphere packing lower bound in high dimensions: discrete geometry.',
 d='GEOM',
 t="Exponential improvement of Minkowski's lower bound for sphere packing in high dimensions",
 s='Let Δ_d be the largest density of a packing of congruent balls in R^d. Is liminf_{d→∞} (1/d) log₂ Δ_d > −1, that is, can the lower bound Δ_d ≥ 2^{−d} (up to polynomial factors) of Minkowski and Hlawka be improved by an exponential factor? Torquato and Stillinger conjecture that disordered packings achieve Δ_d ≥ 2^{−(0.7786…+o(1))d}.',
 c="The best upper bound is Kabatiansky and Levenshtein's Δ_d ≤ 2^{−(0.599…+o(1))d}, so the exponent of Δ_d is known only to lie in [0.599, 1]. All lower bounds come from probabilistic constructions: random lattices, random sequential addition, independent sets in random graphs and random ellipsoids. The analogous question for binary codes, whether the Gilbert–Varshamov bound is asymptotically tight, is also open.",
 src='S. Torquato and F. H. Stillinger, New conjectural lower bounds on the optimal density of sphere packings, Experiment. Math. 15 (2006) 307–331, arXiv:math/0508381',
 loc="Torquato and Stillinger, arXiv:math/0508381, abstract: 'Remarkably, no one has been able to provide exponential improvement on a 100-year-old lower bound on the maximal packing density due to Minkowski in d-dimensional Euclidean space ... we obtain a provisional lower bound on the density whose asymptotic behavior is controlled by 2^{−0.7786... d}, thus providing the putative exponential improvement of Minkowski's bound.'",
 url='https://arxiv.org/abs/math/0508381',
 why='Sphere packing in high dimension is the geometric counterpart of channel coding, and the exponential rate of the optimal density is unknown at both ends. The lower-bound side is a question about how well a random or random-greedy construction can be beaten, which is why probabilistic methods have produced every improvement since Rogers.',
 st='Lower bounds have improved only by polynomial factors: Rogers (c d 2^{−d}), Ball, Vance, Venkatesh (an extra log log d along a sparse sequence of dimensions), Campos, Jenssen, Michelen and Sahasrabudhe (arXiv:2312.10026, (1 − o(1)) d log d / 2^{d+1}), and Klartag (arXiv:2504.05042, a lattice packing of density c d² 2^{−d} from a stochastically evolving ellipsoid). Vanoni, Guo and Torquato (arXiv:2608.00920) show that, conditional on the Torquato–Stillinger realizability conjecture, hyperuniform pair correlations give rates down to 2^{−(0.6226…+o(1))d}, and that the unrestricted pair-correlation programme matches the Cohn–Elkies rate. No exponential improvement is proved. Open.',
 n='Fame: one of the oldest open problems in the geometry of numbers and discrete geometry, prominent in Conway and Sloane and in the recent literature on high-dimensional packings.'),
dict(id="T194", d="IPS", t="Fire lanes in the two-dimensional Drossel–Schwabl forest-fire process",
 s="In the Drossel–Schwabl forest-fire process on Z² (or on the triangular lattice), all sites are vacant at time 0, each vacant site becomes occupied at rate 1, each site is hit by lightning at rate ζ > 0, and a lightning strike burns its entire occupied cluster instantly. Let t_c be the time at which an infinite cluster would first appear without fires. Show that there is δ > 0 such that, as ζ → 0, the probability that the origin burns before time t_c + δ tends to zero, as van den Berg and Nolin proved for the volume-threshold version of the model and expect for the Drossel–Schwabl model.",
 c="The Drossel–Schwabl model is the standard example of self-organised criticality, and physicists predicted that its ζ → 0 limit is critical at all large times; rigorous work suggests a more complicated picture, with recurrent near-critical and off-critical behaviour. Van den Berg and Brouwer (Comm. Math. Phys. 2006) asked whether the origin burns before t_c + δ; for the model with a volume threshold N in place of lightning the answer is negative because of the emergence of fire lanes. Compare T100 (avalanche exponents of the abelian sandpile), another self-organised critical model.",
 src="B. Drossel and F. Schwabl, Self-organized critical forest-fire model, Phys. Rev. Lett. 69 (1992) 1629–1632; J. van den Berg and R. Brouwer, Self-organized forest-fires near the critical time, Comm. Math. Phys. 267 (2006) 265–277",
 loc="J. van den Berg and P. Nolin, A 2D forest fire process beyond the critical time, arXiv:2210.05642, abstract: 'we prove a somewhat counterintuitive result: there exists δ > 0 such that with high probability, the origin does not burn before time t_c + δ. This provides a negative answer to Open Problem 4.1 of van den Berg and Brouwer [Comm. Math. Phys., 2006] ... We expect that such a behavior also holds for the classical Drossel-Schwabl model.'",
 url="https://arxiv.org/abs/2210.05642",
 why="Forest fires are the model through which self-organised criticality entered probability, and the question of what the ζ → 0 limit looks like in two dimensions has resisted rigorous analysis since the 1990s. The fire-lane phenomenon contradicts the simplest physical picture, and proving it for the Drossel–Schwabl dynamics would settle the behaviour near the critical time.",
 st="Kiss, Manolescu and Sidoravicius (Ann. Probab. 2015) analysed planar forest fires near the critical time; van den Berg, Kiss and Nolin proved deconcentration and mesoscopic clusters for volume-frozen percolation; van den Berg and Nolin (arXiv:2210.05642) proved the fire-lane statement for the volume-threshold model and (arXiv:2407.13652) studied fires ignited from the boundary. The infinite-volume Drossel–Schwabl process for fixed ζ exists (Dürre, Electron. J. Probab. 11 (2006)), but its ζ → 0 behaviour beyond the critical time is not understood. Open.",
 n="Fame borderline (my judgment): the forest-fire model is very well known in statistical physics, and the rigorous problem is a standard open question among specialists in planar percolation; the specific fire-lane formulation is recent."),
dict(id='T195',
 x='Moved on 12 Nov 2026 to the list of open problems in mathematics generally (06_math_research/top200_general_2026_11_10, seed_from_probability.tsv): Complexity of #BIS: computational complexity.',
 d='RW',
 t='The complexity of approximately counting independent sets in bipartite graphs (#BIS)',
 s='Is there a fully polynomial randomised approximation scheme for the number of independent sets of a bipartite graph? Dyer, Goldberg, Greenhill and Jerrum conjectured that there is none, while #BIS is also not known to be as hard as approximately counting satisfying assignments of a Boolean formula (#SAT); the problem is to resolve its complexity in either direction.',
 c='#BIS is complete under approximation-preserving reductions for the logically defined class #RHΠ1, so its status decides the approximability of many problems shown to be #BIS-equivalent, among them the ferromagnetic Potts and random-cluster partition functions and counting stable matchings. In the language of Gibbs measures it is the hard-core model at fugacity 1 on bipartite graphs, where Glauber dynamics can mix slowly because of the two sublattice phases.',
 src='M. Dyer, L. A. Goldberg, C. Greenhill and M. Jerrum, The relative complexity of approximate counting problems, Algorithmica 38 (2004) 471–500',
 loc="X. Chen, M. Dyer, L. A. Goldberg, M. Jerrum, P. Lu, C. McQuillan and D. Richerby, The complexity of approximating conservative counting CSPs, arXiv:1208.1783, abstract: '#BIS, the problem of counting independent sets in bipartite graphs. #BIS is complete with respect to approximation-preserving reductions for a logically-defined complexity class #RHPi1, and is believed to be intractable.'",
 url='https://arxiv.org/abs/1208.1783',
 why='#BIS sits at the centre of the complexity classification of approximate counting: a large family of natural problems is equivalent to it, and none of the standard techniques (Markov chains, correlation decay, polynomial interpolation) is known either to solve it or to prove hardness. It is also the cleanest instance of the question whether phase coexistence in a statistical-mechanics model is a genuine algorithmic barrier.',
 st='Algorithms based on cluster expansions and Markov chains exist for restricted classes: bipartite expanders (Jenssen, Keevash and Perkins, arXiv:1807.04804), random regular bipartite graphs (Liao, Lin, Lu and Mao, arXiv:1903.07531; Chen, Galanis, Štefankovič and Vigoda, arXiv:2105.01784) and unbalanced bounded-degree bipartite graphs (Cannon and Perkins, arXiv:1906.01666). Cai, Galanis, Goldberg, Guo, Jerrum, Štefankovič and Vigoda proved #BIS-hardness for antiferromagnetic two-spin systems on bounded-degree bipartite graphs in the non-uniqueness region (J. Comput. System Sci. 82 (2016)). Neither an FPRAS nor NP-hardness is known for #BIS. Open.',
 n="Fame: the best-known open problem in the complexity of approximate counting; Goldberg and Jerrum's work over two decades is organised around it."),
]
